"""Exception hierarchy for minilang."""


class MiniLangError(Exception):
    """Base class. ``str(err)`` is the plain message; ``position`` is a 0-based offset or None."""

    def __init__(self, message, position=None):
        super().__init__(message)
        self.message = message
        self.position = position


class LexError(MiniLangError):
    """Raised for malformed input characters or tokens."""


class ParseError(MiniLangError):
    """Raised when the token stream does not match the grammar."""


class EvalError(MiniLangError):
    """Raised when evaluation fails (type errors, undefined names, etc.)."""

"""Tokenizer for minilang."""

from .errors import LexError

KEYWORDS = frozenset({"true", "false", "and", "or", "not"})
_TWO_CHAR_OPS = frozenset({"==", "!=", "<=", ">="})
_ONE_CHAR_OPS = frozenset("+-*/%^<>(),")
_DIGITS = "0123456789"
_IDENT_START = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_"
_IDENT_CHARS = _IDENT_START + _DIGITS
_WHITESPACE = " \t\r\n"
_ESCAPES = {"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\"}


class Token:
    """A lexical token. ``kind`` is one of NUMBER, STRING, IDENT, KEYWORD, OP."""

    __slots__ = ("kind", "value", "position")

    def __init__(self, kind, value, position):
        self.kind = kind
        self.value = value
        self.position = position

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r}, {self.position})"


def tokenize(source):
    """Split ``source`` into a list of Tokens (no EOF token)."""
    tokens = []
    i = 0
    n = len(source)
    while i < n:
        ch = source[i]
        if ch in _WHITESPACE:
            i += 1
        elif ch == "#":
            end = source.find("\n", i)
            i = n if end == -1 else end
        elif ch == '"':
            i = _lex_string(source, i, tokens)
        elif ch in _DIGITS or (ch == "." and i + 1 < n and source[i + 1] in _DIGITS):
            end = _scan_number(source, i)
            tokens.append(Token("NUMBER", float(source[i:end]), i))
            i = end
        elif ch in _IDENT_START:
            end = i + 1
            while end < n and source[end] in _IDENT_CHARS:
                end += 1
            word = source[i:end]
            kind = "KEYWORD" if word in KEYWORDS else "IDENT"
            tokens.append(Token(kind, word, i))
            i = end
        elif source[i:i + 2] in _TWO_CHAR_OPS:
            tokens.append(Token("OP", source[i:i + 2], i))
            i += 2
        elif ch in _ONE_CHAR_OPS:
            tokens.append(Token("OP", ch, i))
            i += 1
        elif ch == "=":
            raise LexError("unexpected '=' (did you mean '=='?)", i)
        else:
            raise LexError(f"unexpected character {ch!r}", i)
    return tokens


def _scan_number(src, start):
    """Return the end offset of the numeric literal starting at ``start``."""
    n = len(src)
    i = start
    while i < n and src[i] in _DIGITS:
        i += 1
    if i < n and src[i] == ".":
        i += 1
        if not (i < n and src[i] in _DIGITS):
            # "1." is not a valid number; the dot is the offending character
            raise LexError("malformed number: expected digit after '.'", i - 1)
        while i < n and src[i] in _DIGITS:
            i += 1
    if i < n and src[i] in "eE":
        j = i + 1
        if j < n and src[j] in "+-":
            j += 1
        if not (j < n and src[j] in _DIGITS):
            raise LexError("malformed number: expected exponent digits", i)
        i = j
        while i < n and src[i] in _DIGITS:
            i += 1
    return i


def _lex_string(src, start, tokens):
    """Lex a double-quoted string starting at ``start``; return the offset after it."""
    n = len(src)
    i = start + 1
    buf = []
    while True:
        if i >= n:
            raise LexError("unterminated string literal", start)
        ch = src[i]
        if ch == '"':
            break
        if ch == "\n":
            raise LexError("newline inside string literal", i)
        if ch == "\\":
            if i + 1 >= n:
                raise LexError("unterminated string literal", start)
            esc = src[i + 1]
            if esc not in _ESCAPES:
                raise LexError(f"invalid escape sequence '\\{esc}'", i)
            buf.append(_ESCAPES[esc])
            i += 2
            continue
        buf.append(ch)
        i += 1
    tokens.append(Token("STRING", "".join(buf), start))
    return i + 1

"""Recursive-descent parser for minilang. Parsing never evaluates anything."""

from dataclasses import dataclass
from typing import Any

from .errors import ParseError
from .lexer import tokenize

_COMPARISON_OPS = frozenset({"==", "!=", "<", "<=", ">", ">="})


@dataclass(frozen=True)
class Literal:
    value: Any
    position: int


@dataclass(frozen=True)
class Var:
    name: str
    position: int


@dataclass(frozen=True)
class Call:
    name: str
    args: tuple
    position: int


@dataclass(frozen=True)
class Unary:
    op: str  # "-" or "not"
    operand: Any
    position: int


@dataclass(frozen=True)
class Binary:
    op: str  # arithmetic, comparison, "and" or "or"
    left: Any
    right: Any
    position: int


class _Parser:
    def __init__(self, tokens, source_length):
        self._tokens = tokens
        self._pos = 0
        self._end = source_length

    def at_end(self):
        return self._pos >= len(self._tokens)

    def _peek(self):
        return None if self.at_end() else self._tokens[self._pos]

    def _match(self, *values):
        """Consume the next token if it is an operator/keyword whose value is in ``values``."""
        tok = self._peek()
        if tok is not None and tok.kind in ("OP", "KEYWORD") and tok.value in values:
            self._pos += 1
            return tok
        return None

    def _expect(self, value):
        if self._match(value) is None:
            raise self.error(f"expected {value!r}")

    def error(self, message):
        tok = self._peek()
        if tok is None:
            return ParseError(f"{message}, found end of input", self._end)
        return ParseError(f"{message}, found {tok.value!r}", tok.position)

    def _binary_level(self, ops, operand):
        node = operand()
        while True:
            tok = self._match(*ops)
            if tok is None:
                return node
            node = Binary(tok.value, node, operand(), tok.position)

    def expression(self):
        return self._binary_level(("or",), self._and)

    def _and(self):
        return self._binary_level(("and",), self._not)

    def _not(self):
        tok = self._match("not")
        if tok is not None:
            return Unary("not", self._not(), tok.position)
        return self._comparison()

    def _comparison(self):
        left = self._binary_level(("+", "-"), self._multiplicative)
        tok = self._peek()
        if tok is None or tok.kind != "OP" or tok.value not in _COMPARISON_OPS:
            return left
        self._pos += 1
        right = self._binary_level(("+", "-"), self._multiplicative)
        node = Binary(tok.value, left, right, tok.position)
        nxt = self._peek()
        if nxt is not None and nxt.kind == "OP" and nxt.value in _COMPARISON_OPS:
            raise ParseError("comparison operators cannot be chained", nxt.position)
        return node

    def _multiplicative(self):
        return self._binary_level(("*", "/", "%"), self._unary)

    def _unary(self):
        tok = self._match("-")
        if tok is not None:
            return Unary("-", self._unary(), tok.position)
        return self._power()

    def _power(self):
        base = self._primary()
        tok = self._match("^")
        if tok is not None:
            # right-associative; the exponent is a unary so that 2 ^ -1 is valid
            return Binary("^", base, self._unary(), tok.position)
        return base

    def _primary(self):
        tok = self._peek()
        if tok is None:
            raise self.error("expected expression")
        if tok.kind in ("NUMBER", "STRING"):
            self._pos += 1
            return Literal(tok.value, tok.position)
        if tok.kind == "KEYWORD" and tok.value in ("true", "false"):
            self._pos += 1
            return Literal(tok.value == "true", tok.position)
        if tok.kind == "IDENT":
            self._pos += 1
            if self._match("(") is not None:
                return Call(tok.value, tuple(self._arguments()), tok.position)
            return Var(tok.value, tok.position)
        if self._match("(") is not None:
            node = self.expression()
            self._expect(")")
            return node
        raise self.error("expected expression")

    def _arguments(self):
        args = []
        if self._match(")") is not None:
            return args
        while True:
            args.append(self.expression())
            if self._match(",") is not None:
                continue
            self._expect(")")
            return args


def parse(source):
    """Parse ``source`` into an AST. Raises LexError/ParseError; never evaluates."""
    parser = _Parser(tokenize(source), len(source))
    node = parser.expression()
    if not parser.at_end():
        raise parser.error("unexpected token")
    return node

"""Built-in functions and value formatting for minilang."""

import math
import re

from .errors import EvalError

# name -> (min_args, max_args); max_args None means variadic.
ARITY = {
    "abs": (1, 1),
    "min": (1, None),
    "max": (1, None),
    "round": (1, 2),
    "len": (1, 1),
    "upper": (1, 1),
    "lower": (1, 1),
    "str": (1, 1),
    "num": (1, 1),
    "if": (3, 3),  # special-cased by the evaluator so that only the taken branch runs
}

_NUM_RE = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")


def type_name(value):
    if type(value) is bool:
        return "boolean"
    if type(value) is float:
        return "number"
    return "string"


def format_value(value):
    """REPL/str() rendering: integral numbers without decimals, booleans as true/false,
    strings quoted with escapes re-encoded."""
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is float:
        if value.is_integer():
            return str(int(value))
        return repr(value)
    escaped = (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\t", "\\t")
        .replace("\r", "\\r")
    )
    return f'"{escaped}"'


def check_arity(name, count):
    lo, hi = ARITY[name]
    if hi is None:
        expected = f"at least {lo} argument(s)"
    elif lo == hi:
        expected = f"{lo} argument(s)"
    else:
        expected = f"{lo} or {hi} argument(s)"
    if count < lo or (hi is not None and count > hi):
        raise EvalError(f"{name}() takes {expected}, got {count}")


def _need_num(name, value):
    if type(value) is not float:
        raise EvalError(f"{name}() expects a number, got {type_name(value)}")
    return value


def _need_str(name, value):
    if type(value) is not str:
        raise EvalError(f"{name}() expects a string, got {type_name(value)}")
    return value


def _abs(x):
    return abs(_need_num("abs", x))


def _min(*xs):
    return min(_need_num("min", x) for x in xs)


def _max(*xs):
    return max(_need_num("max", x) for x in xs)


def _round(x, n=None):
    _need_num("round", x)
    if n is None:
        try:
            return float(round(x))
        except (OverflowError, ValueError):
            raise EvalError("round() cannot round a non-finite number")
    _need_num("round", n)
    if not (math.isfinite(n) and n == int(n)):
        raise EvalError("round() precision must be a whole number")
    return float(round(x, int(n)))


def _len(s):
    return float(len(_need_str("len", s)))


def _upper(s):
    return _need_str("upper", s).upper()


def _lower(s):
    return _need_str("lower", s).lower()


def _str(x):
    if type(x) is str:
        return x
    return format_value(x)


def _num(s):
    text = _need_str("num", s).strip()
    if not _NUM_RE.fullmatch(text):
        raise EvalError(f"num(): cannot convert {s!r} to a number")
    return float(text)


# Eager builtins; ``if`` is handled by the evaluator.
FUNCTIONS = {
    "abs": _abs,
    "min": _min,
    "max": _max,
    "round": _round,
    "len": _len,
    "upper": _upper,
    "lower": _lower,
    "str": _str,
    "num": _num,
}

"""Tree-walking evaluator for minilang."""

import operator

from .builtins import FUNCTIONS, check_arity, type_name
from .errors import EvalError
from .parser import Binary, Call, Literal, Unary, Var, parse

_VALUE_TYPES = (float, str, bool)
_COMPARE = {
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


def evaluate(source, env=None):
    """Parse and evaluate ``source``. ``env`` is read but never mutated."""
    return _eval(parse(source), {} if env is None else env)


def _eval(node, env):
    if isinstance(node, Literal):
        return node.value
    if isinstance(node, Var):
        return _lookup(node, env)
    if isinstance(node, Unary):
        return _unary(node, env)
    if isinstance(node, Binary):
        return _binary(node, env)
    if isinstance(node, Call):
        return _call(node, env)
    raise EvalError(f"internal error: unknown node {node!r}")


def _lookup(node, env):
    if node.name not in env:
        raise EvalError(f"undefined variable: {node.name}", node.position)
    value = env[node.name]
    if type(value) not in _VALUE_TYPES:
        raise EvalError(f"unsupported value for {node.name}: {value!r}", node.position)
    return value


def _require(kind, value, context):
    ok = type(value) is bool if kind == "bool" else type(value) is float
    if not ok:
        raise EvalError(f"{context} requires a {kind}, got {type_name(value)}")
    return value


def _unary(node, env):
    value = _eval(node.operand, env)
    if node.op == "not":
        return not _require("boolean", value, "'not'")
    return -_require("number", value, "unary '-'")


def _binary(node, env):
    op = node.op
    if op in ("and", "or"):
        return _logical(node, env)
    left = _eval(node.left, env)
    right = _eval(node.right, env)
    if op == "==":
        return _equal(left, right)
    if op == "!=":
        return not _equal(left, right)
    if op in _COMPARE:
        return _ordering(op, left, right)
    if op == "+":
        return _add(left, right)
    if op in ("-", "*", "/", "%", "^"):
        return _arithmetic(node, left, right)
    raise EvalError(f"internal error: unknown operator {op!r}")


def _logical(node, env):
    left = _require("boolean", _eval(node.left, env), f"'{node.op}'")
    if node.op == "and" and not left:
        return False
    if node.op == "or" and left:
        return True
    return _require("boolean", _eval(node.right, env), f"'{node.op}'")


def _equal(a, b):
    return type(a) is type(b) and a == b


def _ordering(op, a, b):
    both_num = type(a) is float and type(b) is float
    both_str = type(a) is str and type(b) is str
    if not (both_num or both_str):
        raise EvalError(f"cannot compare {type_name(a)} with {type_name(b)} using '{op}'")
    return _COMPARE[op](a, b)


def _add(a, b):
    if (type(a) is float and type(b) is float) or (type(a) is str and type(b) is str):
        return a + b
    raise EvalError(f"cannot add {type_name(a)} and {type_name(b)}")


def _arithmetic(node, a, b):
    op = node.op
    if type(a) is not float or type(b) is not float:
        raise EvalError(f"'{op}' requires numbers, got {type_name(a)} and {type_name(b)}")
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            raise EvalError("division by zero", node.position)
        return a / b
    if op == "%":
        if b == 0:
            raise EvalError("modulo by zero", node.position)
        return a % b
    # "^"
    try:
        result = a ** b
    except ZeroDivisionError:
        raise EvalError("zero cannot be raised to a negative power", node.position)
    except OverflowError:
        raise EvalError("numeric overflow in '^'", node.position)
    if isinstance(result, complex):
        raise EvalError("'^' result is not a real number", node.position)
    return result


def _call(node, env):
    name = node.name
    if name not in FUNCTIONS and name != "if":
        raise EvalError(f"undefined function: {name}", node.position)
    check_arity(name, len(node.args))
    if name == "if":
        cond = _require("boolean", _eval(node.args[0], env), "if() condition")
        return _eval(node.args[1] if cond else node.args[2], env)
    args = [_eval(arg, env) for arg in node.args]
    return FUNCTIONS[name](*args)

"""REPL: ``python -m minilang``. Reads one line at a time from stdin."""

import re
import sys

from .builtins import format_value
from .errors import MiniLangError
from .evaluator import evaluate
from .lexer import KEYWORDS

_ASSIGN = re.compile(r"\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)(.*)\Z", re.DOTALL)


def main():
    env = {}
    for raw in sys.stdin:
        line = raw.strip()
        if not line:
            continue
        if line == ":quit":
            return 0
        if line == ":vars":
            for name in sorted(env):
                print(f"{name} = {format_value(env[name])}")
            continue
        try:
            match = _ASSIGN.match(line)
            if match and match.group(1) not in KEYWORDS:
                env[match.group(1)] = evaluate(match.group(2), env)
            else:
                print(format_value(evaluate(line, env)))
        except MiniLangError as exc:
            print(f"error: {exc}")
    return 0


if __name__ == "__main__":
    for stream in (sys.stdin, sys.stdout):
        stream.reconfigure(encoding="utf-8")
    sys.exit(main())

